import React, { useCallback, useEffect, useRef } from "react";

import "./KineticGrid.css";

/* A grid that bends toward the pointer and rings out from every click.
   Ported from the shadcn/Tailwind original to this codebase's stack — plain
   JS, a stylesheet instead of utility classes — with three changes that
   matter here:

   1. The canvas is absolute inside its own wrapper, not fixed to the
      viewport, so it backs one section instead of the whole page.
   2. It paints on a transparent canvas by default, so the page's own
      background and torch stay visible through it. Pass solid to get the
      original's opaque panel back.
   3. It only runs while it is on screen and while something is actually
      moving, because this sits under a form people sit and type in. */

const CELL_SIZE = 55; /* Target cell edge; the real one is W/H divided evenly. */
const INFLUENCE_RADIUS = 260;
const MAX_WARP = 24;
const DOT_SPACING = 28;
const LERP_SPEED = 0.08;

const NODE_BASE_RADIUS = 1.8;
const NODE_ACTIVE_RADIUS = 3.2;

const OFFSCREEN = -9999;

const THEMES = {
  default: {
    bg: "#161618",
    line: { r: 255, g: 255, b: 255, a: 0.13 },
    node: { r: 255, g: 255, b: 255, a: 0.2 },
    dot: "rgba(255,255,255,0.05)",
    active: { r: 74, g: 158, b: 255 },
  },
  monochrome: {
    bg: "#000000",
    line: { r: 255, g: 255, b: 255, a: 0.13 },
    node: { r: 255, g: 255, b: 255, a: 0.2 },
    dot: "rgba(255,255,255,0.05)",
    active: { r: 255, g: 255, b: 255 },
  },
  /* For the light half of the site: the same geometry drawn in ink rather
     than in light, so it reads on a pale body instead of blowing it out. */
  light: {
    bg: "#f4f4f7",
    line: { r: 12, g: 14, b: 22, a: 0.14 },
    node: { r: 12, g: 14, b: 22, a: 0.22 },
    dot: "rgba(12,14,22,0.07)",
    active: { r: 74, g: 158, b: 255 },
  },
};

function lerpN(a, b, t) {
  return a + (b - a) * t;
}

function lerpColor(base, active, t) {
  const r = Math.round(lerpN(base.r, active.r, t));
  const g = Math.round(lerpN(base.g, active.g, t));
  const b = Math.round(lerpN(base.b, active.b, t));
  const a = lerpN(base.a, active.a, t);
  return `rgba(${r},${g},${b},${a.toFixed(3)})`;
}

/* Accepts #rgb, #rrggbb and rgb() so it can take whatever the site theme
   happens to hold in accentColor. Anything else falls back to the theme's
   own active colour rather than throwing. */
function toRgb(value) {
  if (typeof value !== "string") return null;
  const hex = value.trim();
  if (/^#[0-9a-f]{3}$/i.test(hex)) {
    return {
      r: parseInt(hex[1] + hex[1], 16),
      g: parseInt(hex[2] + hex[2], 16),
      b: parseInt(hex[3] + hex[3], 16),
    };
  }
  if (/^#[0-9a-f]{6}$/i.test(hex)) {
    return {
      r: parseInt(hex.slice(1, 3), 16),
      g: parseInt(hex.slice(3, 5), 16),
      b: parseInt(hex.slice(5, 7), 16),
    };
  }
  const m = hex.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);
  if (m) return { r: +m[1], g: +m[2], b: +m[3] };
  return null;
}

export default function KineticGrid({
  children,
  className = "",
  globalColor = "default",
  accent,
  solid = false,
}) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);

  const mouseRef = useRef({ x: OFFSCREEN, y: OFFSCREEN });
  const targetMouseRef = useRef({ x: OFFSCREEN, y: OFFSCREEN });
  const ripplesRef = useRef([]);
  const rafRef = useRef(0);
  const sizeRef = useRef({ w: 0, h: 0 });
  /* Set whenever something happened that the last frame doesn't already
     show — a resize, a theme swap, the first paint. */
  const dirtyRef = useRef(true);

  // ── Warp ──────────────────────────────────────────────────────────────────

  const getWarpedPoint = useCallback(
    (gx, gy, col, row, mouse, ripples, cols, rows) => {
      /* Edge pin — boundary rows and columns stay put, so the section's
         outline never breathes. */
      const edgeMargin = 1.5;
      const colPin = Math.min(col / edgeMargin, (cols - 1 - col) / edgeMargin, 1);
      const rowPin = Math.min(row / edgeMargin, (rows - 1 - row) / edgeMargin, 1);
      const pinFactor = colPin * colPin * rowPin * rowPin;

      const dx = gx - mouse.x;
      const dy = gy - mouse.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      const proximity = Math.max(0, 1 - dist / INFLUENCE_RADIUS) * pinFactor;

      let rx = 0;
      let ry = 0;
      for (const r of ripples) {
        const rdx = gx - r.x;
        const rdy = gy - r.y;
        const rdist = Math.sqrt(rdx * rdx + rdy * rdy);
        const waveWidth = 55;
        const diff = rdist - r.radius;
        if (Math.abs(diff) < waveWidth) {
          const strength =
            (1 - Math.abs(diff) / waveWidth) * r.opacity * 18 * pinFactor;
          const angle = Math.atan2(rdy, rdx);
          const sign = diff < 0 ? -1 : 1;
          rx += Math.cos(angle) * strength * sign * -1;
          ry += Math.sin(angle) * strength * sign * -1;
        }
      }

      if (dist < INFLUENCE_RADIUS && dist > 0 && pinFactor > 0) {
        const t = dist / INFLUENCE_RADIUS;
        const eased = t < 0.01 ? 0 : (1 - t) * (1 - t) * Math.min(1, dist / 60);
        const warpAmt = eased * MAX_WARP * pinFactor;
        const angle = Math.atan2(dy, dx);
        return {
          pt: {
            x: gx - Math.cos(angle) * warpAmt + rx,
            y: gy - Math.sin(angle) * warpAmt + ry,
          },
          proximity,
        };
      }

      return { pt: { x: gx + rx, y: gy + ry }, proximity };
    },
    [],
  );

  // ── Draw ──────────────────────────────────────────────────────────────────

  const draw = useCallback(
    (now) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const { w: W, h: H } = sizeRef.current;
      if (!W || !H) return;

      const mouse = mouseRef.current;
      const ripples = ripplesRef.current;

      const base = THEMES[globalColor] || THEMES.default;
      const activeRgb = toRgb(accent) || base.active;
      const lineActive = { ...activeRgb, a: 0.9 };
      const nodeActive = { ...activeRgb, a: 1 };
      const glow = `${activeRgb.r},${activeRgb.g},${activeRgb.b}`;

      ctx.clearRect(0, 0, W, H);

      if (solid) {
        ctx.fillStyle = base.bg;
        ctx.fillRect(0, 0, W, H);
      }

      /* Static dot texture under the grid. */
      ctx.fillStyle = base.dot;
      for (let x = DOT_SPACING / 2; x < W; x += DOT_SPACING) {
        for (let y = DOT_SPACING / 2; y < H; y += DOT_SPACING) {
          ctx.beginPath();
          ctx.arc(x, y, 0.7, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      for (let i = ripples.length - 1; i >= 0; i--) {
        const r = ripples[i];
        const age = (now - r.born) / 1000;
        r.radius = Math.max(0, age * 400);
        r.opacity = Math.max(0, 1 - age * 1.2);
        if (r.opacity <= 0) ripples.splice(i, 1);
      }

      // ── Warped lattice ──────────────────────────────────────────────────
      const cols = Math.max(2, Math.ceil(W / CELL_SIZE)) + 1;
      const rows = Math.max(2, Math.ceil(H / CELL_SIZE)) + 1;
      const cellW = W / (cols - 1);
      const cellH = H / (rows - 1);

      const pts = [];
      const prox = [];

      for (let row = 0; row < rows; row++) {
        pts[row] = [];
        prox[row] = [];
        for (let col = 0; col < cols; col++) {
          const { pt, proximity } = getWarpedPoint(
            col * cellW,
            row * cellH,
            col,
            row,
            mouse,
            ripples,
            cols,
            rows,
          );
          pts[row][col] = pt;
          prox[row][col] = proximity;
        }
      }

      // ── Lines ───────────────────────────────────────────────────────────
      const drawSeg = (p1, p2, pr1, pr2) => {
        const avg = (pr1 + pr2) / 2;
        const t = avg * avg * (3 - 2 * avg); /* smoothstep */
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = lerpColor(base.line, lineActive, t);
        ctx.lineWidth = lerpN(0.8, 1.5, t);
        ctx.stroke();
      };

      ctx.lineCap = "butt";

      for (let row = 0; row < rows; row++)
        for (let col = 0; col < cols - 1; col++)
          drawSeg(
            pts[row][col],
            pts[row][col + 1],
            prox[row][col],
            prox[row][col + 1],
          );

      for (let col = 0; col < cols; col++)
        for (let row = 0; row < rows - 1; row++)
          drawSeg(
            pts[row][col],
            pts[row + 1][col],
            prox[row][col],
            prox[row + 1][col],
          );

      // ── Intersection nodes ──────────────────────────────────────────────
      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const p = pts[row][col];
          const pr = prox[row][col];
          const t = pr * pr * (3 - 2 * pr);
          const r = lerpN(NODE_BASE_RADIUS, NODE_ACTIVE_RADIUS, t);

          if (t > 0.3) {
            const glowR = r + lerpN(0, 6, (t - 0.3) / 0.7);
            const grd = ctx.createRadialGradient(
              p.x,
              p.y,
              r * 0.5,
              p.x,
              p.y,
              glowR,
            );
            grd.addColorStop(0, `rgba(${glow},${(t * 0.3).toFixed(3)})`);
            grd.addColorStop(1, `rgba(${glow},0)`);
            ctx.beginPath();
            ctx.arc(p.x, p.y, glowR, 0, Math.PI * 2);
            ctx.fillStyle = grd;
            ctx.fill();
          }

          ctx.beginPath();
          ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
          ctx.fillStyle = lerpColor(base.node, nodeActive, t);
          ctx.fill();
        }
      }

      // ── Ripple rings ────────────────────────────────────────────────────
      for (const r of ripples) {
        ctx.beginPath();
        ctx.arc(r.x, r.y, Math.max(0, r.radius), 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(${glow},${(r.opacity * 0.28).toFixed(3)})`;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }
    },
    [accent, getWarpedPoint, globalColor, solid],
  );

  // ── Loop ──────────────────────────────────────────────────────────────────

  const animate = useCallback(
    (now) => {
      const m = mouseRef.current;
      const t = targetMouseRef.current;
      const settling =
        Math.abs(m.x - t.x) > 0.2 || Math.abs(m.y - t.y) > 0.2;

      if (settling) {
        m.x = lerpN(m.x, t.x, LERP_SPEED);
        m.y = lerpN(m.y, t.y, LERP_SPEED);
      }

      /* Nothing moving and nothing ringing means the last frame is still
         correct — a form page shouldn't repaint a canvas 60 times a second
         to show the same picture. */
      if (settling || ripplesRef.current.length > 0 || dirtyRef.current) {
        draw(now);
        dirtyRef.current = false;
      }

      rafRef.current = requestAnimationFrame(animate);
    },
    [draw],
  );

  // ── Setup ─────────────────────────────────────────────────────────────────

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap) return undefined;

    const reduced =
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const setSize = () => {
      const rect = wrap.getBoundingClientRect();
      const w = Math.round(rect.width);
      const h = Math.round(rect.height);
      if (!w || !h) return;
      /* Backing store at device resolution, drawing units in CSS pixels —
         without this the hairlines are soft on every retina screen. */
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      const ctx = canvas.getContext("2d");
      if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sizeRef.current = { w, h };
      dirtyRef.current = true;
      if (reduced) draw(performance.now());
    };

    setSize();

    let ro = null;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(setSize);
      ro.observe(wrap);
    }
    window.addEventListener("resize", setSize);

    /* Reduced motion gets the lattice, still, and none of the listeners. */
    if (reduced) {
      return () => {
        window.removeEventListener("resize", setSize);
        if (ro) ro.disconnect();
      };
    }

    /* Tracked on the window rather than the wrapper so the grid starts
       leaning before the pointer crosses the section's edge; the coordinates
       are converted into the wrapper's own space. */
    const onMouseMove = (e) => {
      const rect = wrap.getBoundingClientRect();
      targetMouseRef.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      };
    };

    const onClick = (e) => {
      const rect = wrap.getBoundingClientRect();
      ripplesRef.current.push({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        radius: 0,
        opacity: 1,
        born: performance.now(),
      });
    };

    window.addEventListener("mousemove", onMouseMove, { passive: true });
    /* Clicks only count inside the section — a click anywhere else on the
       page has nothing to do with this grid. */
    wrap.addEventListener("click", onClick);

    const start = () => {
      if (!rafRef.current) {
        dirtyRef.current = true;
        rafRef.current = requestAnimationFrame(animate);
      }
    };
    const stop = () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = 0;
      }
    };

    /* Off screen, the loop stops outright. */
    let io = null;
    if (typeof IntersectionObserver !== "undefined") {
      io = new IntersectionObserver(
        ([entry]) => (entry.isIntersecting ? start() : stop()),
        { rootMargin: "120px" },
      );
      io.observe(wrap);
    } else {
      start();
    }

    return () => {
      stop();
      window.removeEventListener("resize", setSize);
      window.removeEventListener("mousemove", onMouseMove);
      wrap.removeEventListener("click", onClick);
      if (ro) ro.disconnect();
      if (io) io.disconnect();
    };
  }, [animate, draw]);

  /* A theme or accent change has to repaint even if the pointer is parked. */
  useEffect(() => {
    dirtyRef.current = true;
  }, [accent, globalColor, solid]);

  return (
    <div
      ref={wrapRef}
      className={`kgrid${solid ? " is-solid" : ""}${
        className ? ` ${className}` : ""
      }`}
      data-tone={globalColor}
    >
      <canvas ref={canvasRef} className="kgrid-canvas" aria-hidden="true" />
      <div className="kgrid-content">{children}</div>
    </div>
  );
}
