/* ============================================================
   Pip — the contact form's companion.

   Sits beside the form and waits. It reacts to how much of the message is
   written: idles and cycles "still waiting" thoughts while the form is
   empty, cheers each field as it lands, and thanks you once the message
   is sendable. While sending it holds the envelope up; once sent it waves
   the letter off.

   It shares its techniques with pages/projects/LilAgents (SVG sprite,
   CSS-driven bob and blink, pupils tracking the cursor through --eye-x /
   --eye-y) but not its artwork or its personality — Bolt and Pixel are
   robots that stroll across the projects hero; Pip is a postal creature
   that stays put and watches one form.

   `stage` is 0-4: how many of the four fields currently validate.
   ============================================================ */
import React, { useEffect, useRef, useState } from "react";
import "./FormCompanion.css";

const reduced = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/* What Pip is thinking, per stage. Stage 0 cycles while nothing happens;
   the rest are one-shot reactions to a field landing. */
const IDLE_THOUGHTS = [
  "waiting for you…",
  "tell me anything",
  "I'll pass it straight on ✉️",
  "still here 👀",
  "no rush",
];

const STAGE_THOUGHTS = [
  null, // 0 — handled by the idle cycle
  "got your name!",
  "…and where to reply",
  "ooh, a subject",
  "thank you! 💛",
];

export default function FormCompanion({ stage, waiting, sending, sent }) {
  const svgRef = useRef(null);
  const [idleIdx, setIdleIdx] = useState(0);

  const ready = stage >= 4;

  /* Pupils follow the cursor. Same trick as LilAgents: one rAF-batched
     listener writing two custom properties, never React state. */
  useEffect(() => {
    if (reduced()) return undefined;
    if (window.matchMedia && !window.matchMedia("(pointer: fine)").matches)
      return undefined;
    const svg = svgRef.current;
    if (!svg) return undefined;
    let raf = null;
    const onMove = (e) => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = null;
        const r = svg.getBoundingClientRect();
        const dx = e.clientX - (r.left + r.width / 2);
        const dy = e.clientY - (r.top + r.height / 2);
        const len = Math.max(Math.hypot(dx, dy), 1);
        svg.style.setProperty("--eye-x", `${((dx / len) * 1.7).toFixed(2)}px`);
        svg.style.setProperty("--eye-y", `${((dy / len) * 1.2).toFixed(2)}px`);
      });
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => {
      window.removeEventListener("mousemove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  /* The idle thoughts only advance while Pip is actually idle, so they are
     not quietly cycling behind a visitor who is mid-sentence. */
  useEffect(() => {
    if (!waiting || stage > 0) return undefined;
    const id = setInterval(
      () => setIdleIdx((i) => (i + 1) % IDLE_THOUGHTS.length),
      3800
    );
    return () => clearInterval(id);
  }, [waiting, stage]);

  let mood = "idle";
  if (sent) mood = "sent";
  else if (sending) mood = "sending";
  else if (ready) mood = "happy";
  else if (stage > 0) mood = "cheer";
  else if (waiting) mood = "waiting";

  let thought = null;
  if (sent) thought = "off it goes! 🕊️";
  else if (sending) thought = "sending…";
  else if (stage > 0) thought = STAGE_THOUGHTS[Math.min(stage, 4)];
  else if (waiting) thought = IDLE_THOUGHTS[idleIdx];

  return (
    <div
      className="pip"
      data-mood={mood}
      style={{ "--s": stage / 4 }}
      aria-hidden="true"
    >
      {/* Pip's thought. aria-hidden on the wrapper: the progress rail below
          already announces the same state to a screen reader, and two
          voices saying it would be noise. */}
      <div className="pip-bubble" data-shown={thought ? "1" : "0"}>
        <span key={thought}>{thought}</span>
      </div>

      <svg className="pip-svg" ref={svgRef} viewBox="0 0 96 92">
        <ellipse className="pip-shadow" cx="48" cy="86" rx="20" ry="3.6" />

        <g className="pip-bob">
          {/* the letter Pip is holding, which fills in as the form does */}
          <g className="pip-letter">
            <rect x="30" y="12" width="36" height="26" rx="3" />
            <path className="pip-letter-flap" d="M30 14 L48 27 L66 14" />
            <g className="pip-letter-lines">
              <line x1="36" y1="22" x2="56" y2="22" />
              <line x1="36" y1="28" x2="60" y2="28" />
              <line x1="36" y1="34" x2="50" y2="34" />
            </g>
          </g>

          {/* body */}
          <path
            className="pip-body"
            d="M24 84 L24 52 a24 24 0 0 1 48 0 L72 84 a6 6 0 0 1 -6 6 L30 90 a6 6 0 0 1 -6 -6 Z"
          />
          {/* satchel strap, so it reads as a courier and not a blob */}
          <path className="pip-strap" d="M30 56 L66 74" />
          <rect
            className="pip-satchel"
            x="60"
            y="66"
            width="16"
            height="13"
            rx="3"
          />

          {/* face plate */}
          <ellipse className="pip-face" cx="48" cy="60" rx="17" ry="14" />

          <g className="pip-eyes">
            <g className="pip-eye">
              <circle cx="42" cy="59" r="3.1" />
            </g>
            <g className="pip-eye">
              <circle cx="54" cy="59" r="3.1" />
            </g>
          </g>

          {/* mouth: a small o while waiting, a smile once thanked */}
          <path className="pip-smile" d="M43.5 66.5 q4.5 4 9 0" />

          <g className="pip-blush">
            <ellipse cx="36" cy="65" rx="3.2" ry="1.9" />
            <ellipse cx="60" cy="65" rx="3.2" ry="1.9" />
          </g>

          {/* arms — they lift when Pip is pleased */}
          <path className="pip-arm pip-arm-l" d="M25 62 q-8 4 -7 12" />
          <path className="pip-arm pip-arm-r" d="M71 62 q8 4 7 12" />
        </g>

        {/* one heart per completed field, popping in as they land */}
        <g className="pip-hearts">
          {[0, 1, 2, 3].map((i) => (
            <text
              key={i}
              className={`pip-heart${stage > i ? " is-on" : ""}`}
              x={22 + i * 17}
              y="10"
              style={{ "--i": i }}
            >
              ♥
            </text>
          ))}
        </g>
      </svg>
    </div>
  );
}
